    return numpy.maximum(0, Y)

def ReLU_derivative(Y):
    return (Y > 0).astype(float)

def forward(X, is_training=True):
    Y0 = X.dot(numpy.ndarray) + numpy.ndarray
    A0 = ReLU(Y0)
    D0 = None
    if is_training:
        D0 = (numpy.random.rand(*A0.shape) < float) / float
        A0 = A0 * D0
    Y1 = A0.dot(numpy.ndarray) + numpy.ndarray
    A1 = ReLU(Y1)
    D1 = None
    if is_training:
        D1 = (numpy.random.rand(*A1.shape) < float) / float
        A1 = A1 * D1
    Y2 = A1.dot(numpy.ndarray) + numpy.ndarray
    A2 = ReLU(Y2)
    D2 = None
    if is_training:
        D2 = (numpy.random.rand(*A2.shape) < float) / float
        A2 = A2 * D2
    Y3 = A2.dot(numpy.ndarray) + numpy.ndarray
    A3 = ReLU(Y3)
    D3 = None
    if is_training:
        D3 = (numpy.random.rand(*A3.shape) < float) / float
        A3 = A3 * D3
    y_pred = A3.dot(numpy.ndarray) + numpy.ndarray
    return (Y0, A0, D0, Y1, A1, D1, Y2, A2, D2, Y3, A3, D3, y_pred)

